<script setup lang="ts">
import type { UsageSummary, UsageEntry } from '../../../shared/billing';
import { formatDate } from '../api';
defineProps<{summary?:UsageSummary;entries:UsageEntry[]}>();
const stages:Record<string,string>={generation:'生成',followup:'AI 跟进',evaluation:'独立评测',delivery:'交付核验'};
</script>
<template><section class="panel settings-panel"><h2>模型用量与费用</h2><div v-if="summary?.requests" class="usage-summary"><strong>{{summary.priced?`¥ ${summary.knownCny.toFixed(6)}`:'金额待核算'}}</strong><span>已知用量估算{{summary.missing?'小计':''}}</span><span>输入 {{summary.input.toLocaleString()}} · 缓存命中 {{summary.cached.toLocaleString()}} · 输出 {{summary.output.toLocaleString()}} tokens</span><span v-if="summary.missing" class="warning-text">{{summary.missing}} 条待核算</span></div><p v-else class="text-muted">尚未收到实际 usage；历史任务不能据此视为零费用。</p><p class="text-muted small-text">按请求的模型、北京时间时段和固定价格版本估算，最终以官方账单为准。后台压缩、未返回 usage 的失败重试及独立 Search / Fetch 费用可能未包含。生成任务包含自动交接的评测子任务，勿再重复相加。</p><details v-if="entries.length"><summary>查看 {{entries.length}} 条用量明细</summary><div class="table-scroll"><table class="task-table"><thead><tr><th>阶段 / 模型</th><th>请求时间</th><th>输入 / 缓存 / 输出</th><th>时段 / 金额</th><th>记录依据</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.taskId+entry.source+entry.id"><td>{{stages[entry.stage]}}<span class="table-subtitle">{{entry.model}}</span></td><td>{{formatDate(entry.startedAt)}}<span class="table-subtitle">{{entry.status}}</span></td><td>{{entry.tokens?`${entry.tokens.input} / ${entry.tokens.cached??'未知'} / ${entry.tokens.output}`:'用量缺失'}}</td><td>{{({peak:'高峰',offpeak:'闲时',mixed:'跨时段',unknown:'未知'})[entry.band]}}<span class="table-subtitle">{{entry.cny===null?'待核算':`¥ ${entry.cny.toFixed(6)}`}}</span></td><td class="wrapping-cell">{{entry.note||'请求级 usage'}}<span class="table-subtitle">价格版本：{{entry.price?.id||'未匹配'}}</span><details><summary>原始 usage</summary><pre>{{JSON.stringify(entry.raw,null,2)}}</pre></details></td></tr></tbody></table></div></details></section></template>
